"""Build reviewed application snapshots from executed model artifacts."""
from pathlib import Path
import json,sys
from datetime import datetime,timezone
ROOT=Path(__file__).resolve().parent
OUT=ROOT.parent/'work/showcase-expansion'

def snapshot(name):
 a=json.loads((ROOT/name/'artifacts/analysis.json').read_text());s=a['source']
 source={'label':s['classification'],'provider':'Kaggle','url':s['url'],'classification':s['classification'],'notes':[s['credit'],s['license']],'evidenceFlow':[{'title':'Source archive','detail':s['download']},{'title':'Verified SHA-256','detail':s['sha256']},{'title':'Reproduce','detail':'python pipeline.py; see executed analysis.ipynb and tests.'}]}
 def q(rows,label,notes=()):return {'rows':rows,'source':{**source,'label':label,'notes':source['notes']+list(notes)}}
 if name=='grid-forecast':
  queries={'forecast':q(a['rows'],'2017 day-ahead replay',['Predictions made using calendar data and demand lags available by 23:00 the previous day.','Source timestamps are timezone-naive; duplicate timestamps are averaged, gaps are preserved, incomplete rows excluded.']), 'daily':q(a['daily'],'Daily held-out evaluation'), 'monthly':q(a['monthly'],'Monthly held-out errors'), 'metrics':q(a['metrics'],'2017 baseline comparison'), 'candidates':q(a['candidates'],'Expanding validation: 2014 and 2015'), 'summary':q([{**a['quality'],'winner':a['winner'],'radius':a['radius'],'coverage':a['coverage'],'ci_low':a['mae_ci95'][0],'ci_high':a['mae_ci95'][1]}],'Evaluation and quality contract')}
  filters=[{'id':'date','label':'Forecast day','field':'date','defaultValue':'2017-08-25','queryIds':['forecast','daily']}];title='Grid Forecast Lab'
 else:
  notes=['Synthetic videos, generated by the source author. No actual YouTube observations.','The viral label is the top 20% of views. Engagement metrics are computed from views.','Models fit 7,200 training rows using three-fold sigmoid calibration; 2,400 validation rows select the metadata model. A separate 2,400-row test set is used for evaluation.','Threshold and cohort controls explore fixed test predictions; their choices are not newly validated policies.']
  queries={'videos':q(a['rows'],'Held-out synthetic videos',notes),'metrics':q(a['metrics'],'Fixed-threshold test evaluation',notes),'candidates':q(a['candidates'],'Validation model comparison',notes),'calibration':q(a['calibration'],'Test probability calibration',notes),'importance':q(a['importance'],'Validation permutation importance',notes),'summary':q([{**a['quality'],'winner':a['winner'],'ci_low':a['auc_ci95'][0],'ci_high':a['auc_ci95'][1]}],'Source quality and evaluation',notes)}
  filters=[{'id':'category','label':'Video category','field':'category','defaultValue':'all','queryIds':['videos']}];title='Video Signal Lab'
 return {'surface':'dashboard','title':title,'status':'reviewed','buildStatus':'complete','generatedAt':datetime.now(timezone.utc).isoformat(),'filters':filters,'queries':queries}
if __name__=='__main__':
 for name in (sys.argv[1:] or ['grid-forecast','video-signal']):
  data=snapshot(name);path=OUT/f'{name}-snapshot.json';path.write_text(json.dumps(data,separators=(',',':'),allow_nan=False))
  app=OUT/'apps'/name/'src/data.json'
  if app.exists():
   data['id']=json.loads(app.read_text())['id'];app.write_text(json.dumps(data,separators=(',',':'),allow_nan=False))
